public static class FinalizeSevenScene{public static string Main(){EditorSceneManager.OpenScene("Assets/Scenes/LakeWoods.unity");var cave=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title=="Echo Cave");cave.aiValidated=true;EditorUtility.SetDirty(cave);EditorSceneManager.MarkSceneDirty(cave.gameObject.scene);EditorSceneManager.SaveScene(cave.gameObject.scene);EditorSceneManager.OpenScene("Assets/Scenes/DansBackyardReverse.unity");var drain=Object.FindObjectsByType<WoodlandRoute>().Single(b=>b.title.StartsWith("Storm"));var g=new GameObject("Drain threshold recovery exclusion");g.transform.SetParent(drain.transform,false);var exclusion=g.AddComponent<JumpRecoveryExclusion>();exclusion.start=drain.At(0,out _);exclusion.end=drain.At(25,out _);exclusion.halfWidth=5;EditorSceneManager.MarkSceneDirty(g.scene);EditorSceneManager.SaveScene(g.scene);PlayerSettings.bundleVersion="0.57.0-review1";var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Resources/VehicleGlazing.mat");mat.SetFloat("_SrcBlend",1);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();AssetDatabase.Refresh();return "Forward cave AI eligible; drain threshold excluded from recovery; version set";}}
